+   UPDATE interaction_comment_total SET comments=comments-1,roots=roots-CASE WHEN OLD.parent_id IS NULL THEN 1 ELSE 0 END
+   WHERE target_id=OLD.target_id AND root_id=OLD.root_id AND author_id=OLD.author_id;
