+   INSERT INTO interaction_comment_total(target_id,root_id,author_id,comments,roots)
+   VALUES(NEW.target_id,NEW.root_id,NEW.author_id,1,CASE WHEN NEW.parent_id IS NULL THEN 1 ELSE 0 END)
