+   WHEN 'comment.create' THEN 'comment' WHEN 'comment.edit' THEN 'edit'
+   WHEN 'comment.hide' THEN 'moderation' WHEN 'comment.remove' THEN 'moderation' END,
+   'commentId',CASE WHEN op LIKE 'comment.%' THEN c.id END);
