+-- A resolved report may reopen only after the author changes content.
+-- Content versions exclude hide/restore and no-op edits, and retain no body hash.
+BEGIN;
+SET LOCAL lock_timeout='5s';
+ALTER TABLE interaction_comment ADD COLUMN IF NOT EXISTS content_version bigint;
+UPDATE interaction_comment SET content_version=version WHERE content_version IS NULL;
+ALTER TABLE interaction_comment ALTER COLUMN content_version SET DEFAULT 1;
+ALTER TABLE interaction_comment ALTER COLUMN content_version SET NOT NULL;
+ALTER TABLE interaction_comment DROP CONSTRAINT IF EXISTS interaction_comment_content_version_check;
+ALTER TABLE interaction_comment ADD CONSTRAINT interaction_comment_content_version_check CHECK(content_version>=1 AND content_version<=version);
+ALTER TABLE interaction_report ADD COLUMN IF NOT EXISTS reported_version bigint;
+-- Earlier reports have no trustworthy historical version; retain their evidence
+-- and conservatively baseline current content without reopening anything.
+UPDATE interaction_report report SET reported_version=c.content_version
+ FROM interaction_comment c WHERE c.id=report.comment_id AND report.reported_version IS NULL;
+ALTER TABLE interaction_report ALTER COLUMN reported_version SET NOT NULL;
+ALTER TABLE interaction_report DROP CONSTRAINT IF EXISTS interaction_report_version_check;
+ALTER TABLE interaction_report ADD CONSTRAINT interaction_report_version_check CHECK(reported_version>=1);
+CREATE OR REPLACE FUNCTION interaction_mentions_changed(comment_key uuid,mentions jsonb)
+RETURNS boolean LANGUAGE sql STABLE AS $$
+ SELECT coalesce((SELECT jsonb_agg(jsonb_build_array(party_id,start_offset,end_offset) ORDER BY start_offset)
+   FROM interaction_comment_mention WHERE comment_id=comment_key),'[]'::jsonb)
+ IS DISTINCT FROM coalesce((SELECT jsonb_agg(jsonb_build_array((m->>'partyId')::bigint,(m->>'start')::integer,(m->>'end')::integer)
+   ORDER BY (m->>'start')::integer) FROM jsonb_array_elements(mentions) m),'[]'::jsonb)
+$$;
+CREATE OR REPLACE FUNCTION interaction_command(actor bigint,target uuid,request_id uuid,payload jsonb)
+RETURNS jsonb LANGUAGE plpgsql AS $$
+DECLARE context jsonb; op text; fingerprint text; prior interaction_request%ROWTYPE;
+ t interaction_target%ROWTYPE; c interaction_comment%ROWTYPE; parent interaction_comment%ROWTYPE;
+ result_value jsonb; body_value text; mentions jsonb; comment_key uuid; parent_key uuid;
+ initial_context jsonb; moderating boolean:=false; reaction_changed boolean:=false; new_mentions bigint[];
+ reaction_key uuid; next_state text; reason_value text; expected bigint; allowed_keys text[];
+BEGIN
+ IF NOT interaction_writes_enabled() THEN RETURN '{"error":"disabled"}'; END IF;
+ IF actor IS NULL OR request_id IS NULL OR jsonb_typeof(payload) IS DISTINCT FROM 'object'
+   OR pg_column_size(payload)>32768 OR NOT interaction_actor_live(actor) THEN RETURN '{"error":"invalid"}'; END IF;
+ op:=payload->>'operation';
+ allowed_keys:=CASE op
